// Learn mode script for Dental Science lab 01.
// Each step names the tool to use, the scene object to click, the action event
// that completes it, and what to teach. ok(ev) returns true or a correction
// (the student redoes the step). need lists phrases the narration should include.
import {DENTAL_PATTERNS as RX} from './mock-lab-dental-rubric.js';

const allOk = msg => e => (e.d.ok || []).every(Boolean) ? true : msg;
const hygieneOk = e => e.d.method === 'wash' || e.d.method === 'rub' ? true : 'Water alone is not hand hygiene. Choose soap and water or alcohol-based hand rub.';
const hygiene = (phase, why) => ({tool: 'hygiene', hot: 'sink', ev: 'hygiene', phase, title: 'Hand hygiene', do: 'Click the sink and choose Hand hygiene. Pick soap and water or alcohol-based hand rub.', why, say: 'Using alcohol-based hand rub until my hands are dry.', ok: hygieneOk, need: [[RX.hygiene, 'washing or hand rub']]});
const ppe = (phase, again) => [
  {tool: 'gown', hot: 'ppe', ev: 'gown', phase, title: again ? 'Gown on again' : 'Put on the gown',
    do: 'Click the PPE station and choose Gown. Answer each step.', why: 'The gown goes on first. It must cover you from neck to knees and arms to wrists, wrap around the back, and tie at the neck and waist.',
    say: 'Putting on my gown, covering neck to knees, tied at the neck and waist.', ok: allOk('One gown choice was wrong. Look for the ★ coach picks.')},
  {tool: 'mask', hot: 'ppe', ev: 'mask', phase, title: again ? 'Mask on again' : 'Put on the mask',
    do: 'Click the PPE station and choose Mask.', why: 'Mask second. Secure the ties or ear loops, pinch the flexible band to your nose, and pull it snug under your chin.',
    say: 'Mask on, fitting the nose band and snug below my chin.', ok: allOk('One mask choice was wrong. Look for the ★ coach picks.')},
  {tool: 'eyewear', hot: 'ppe', ev: 'eyewear', phase, title: again ? 'Eyewear on again' : 'Put on protective eyewear',
    do: 'Click the PPE station and choose Eyewear.', why: 'Eyewear goes over your face and eyes and sits over the mask. It protects you from spatter.',
    say: 'Protective eyewear on over my mask.', ok: allOk('One eyewear choice was wrong. Look for the ★ coach picks.')}
];

